const companies = [
  { name: 'Orange', url: 'https://www.orange.es/tarifas' },

];

const items = [];


for (const company of companies) {
  items.push({
    json: {
      company: company.name,
      targetUrl: company.url
    }
  });
}


return items;

const out = [];

// 1. Obtenemos el HTML de la entrada
const htmlText = $input.first().json.data || $input.first().json.texto_limpio || $input.first().json.body || "";

if (!htmlText) {
    return [{ json: { error: "El HTML de Orange llegó vacío." } }];
}

// 2. PARSER DE ORANGE
// Cortamos el HTML por cada bloque de tarjeta de tarifa
const blocks = htmlText.split('class="card-tariff-new');

for (let i = 1; i < blocks.length; i++) {
    const block = blocks[i];

    // Extraer datos del input hidden (Nombre, ID y Precio base)
    const dataMatch = block.match(/dataSimpleTariff[^>]*data-price="([^"]+)"[^>]*data-name="([^"]+)"/);
    if (!dataMatch) continue;

    const precioBase = parseFloat(dataMatch[1]);
    const nombreTecnico = dataMatch[2];

    // Extraer el Título comercial (Ej: Cine y Series con 1 línea)
    const titleMatch = block.match(/card-tariff-new__header[^>]*>\s*([\s\S]*?)\s*<\/div>/);
    const nombreComercial = titleMatch ? titleMatch[1].trim() : nombreTecnico;

    // Extraer características (Soporta formatos nuevos con __features__ o __features-simple__)
    let condiciones = [];
    const featureRegex = /card-tariff-(?:new|simple)__features__main[^>]*>\s*([\s\S]*?)\s*<\/div>/g;
    let featureM;
    while ((featureM = featureRegex.exec(block)) !== null) {
        let text = featureM[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        if (text) condiciones.push("- " + text);
    }

    // Extraer servicios de streaming incluidos leyendo los iconos directamente del bloque
    if (block.includes('iconassets__disney-plus') && !block.includes('card-tariff-simple__features__item--disabled"> <hl-icon name="iconassets__disney-plus')) {
        condiciones.push("- Incluye Disney+");
    }
    if (block.includes('iconassets__netflix-mini') && !block.includes('card-tariff-simple__features__item--disabled"> <hl-icon name="iconassets__netflix-mini')) {
        condiciones.push("- Incluye Netflix");
    }

    // Extraer Precio Promocional (Buscamos la etiqueta <hl-price-block> que no sea 'is-old')
    let precioFinal = precioBase;
    const priceBlocks = block.split('<hl-price-block');

    for (let p = 1; p < priceBlocks.length; p++) {
        const pBlock = priceBlocks[p];
        // Si no es el precio antiguo (tachado), nos quedamos con este valor
        if (!pBlock.includes('is-old="true"') && !pBlock.includes('price-block--is-old')) {
            const unitMatch = pBlock.match(/unit="(\d+)"/);
            if (unitMatch) {
                precioFinal = parseFloat(unitMatch[1]);
                break;
            }
        }
    }

    // Extraer URL de "Más info"
    let url_oferta = null;
    const urlMatch = block.match(/href="([^"]+)"[^>]*class="[^"]*js-more-info-tariff/);
    if (urlMatch) {
        url_oferta = urlMatch[1].startsWith('http') ? urlMatch[1] : "https://www.orange.es" + urlMatch[1];
    }

    // Extraer texto extra de promociones (Ej: Líneas adicionales gratis)
    const rewardMatch = block.match(/card-tariff-simple__features__main[^>]*>\s*([\s\S]*?)\s*<\/div>/);
    if (rewardMatch && rewardMatch[1].includes('¡Incluye')) {
        let textReward = rewardMatch[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        condiciones.push("- Promo: " + textReward);
    }

    out.push({
        json: {
            id_proveedor: 14,
            id_tipo_servicio: 3,
            nombre_tarifa: nombreComercial,
            precio: precioFinal,
            precio_fuera_promo: precioBase,
            unidad_precio: "€/mes",
            permanencia: block.toLowerCase().includes("sin permanencia") ? "Sin permanencia" : "12 meses",
            condiciones: condiciones.join('\n'),
            url_oferta_externa: url_oferta || "https://www.orange.es/tarifas"
        }
    });
}

// Limpiar duplicados por nombre de tarifa
const uniqueOut = Array.from(new Map(out.map(item => [item.json.nombre_tarifa, item])).values());

if (uniqueOut.length === 0) {
    return [{ json: { error: "No se detectaron tarifas de Orange. Revisa las clases del HTML." } }];
}

return uniqueOut;
